SINA_SMART["anat3-sinuses"] = {"lecture":"anat3-sinuses","title":"Nose and paranasal sinuses","mapStatus":"auto: generated by universal.py from the lecture summary and key points; not human-reviewed","los":[{"id":"anat3-sinuses:s0","text":"Describe and explain: The big picture","topic":"The big picture","sec":0,"importance":"standard","highYield":"untested"},{"id":"anat3-sinuses:e0","text":"Nares open onto the face; choanae open into the nasopharynx.","topic":"The nasal cavity","sec":1,"importance":"core","highYield":"untested"},{"id":"anat3-sinuses:e1","text":"Four air channels: inferior, middle and superior meatuses plus the spheno-ethmoidal recess.","topic":"The nasal cavity","sec":1,"importance":"core","highYield":"untested"},{"id":"anat3-sinuses:e6","text":"Maxillary: the largest, 3.5 x 2.5 x 3.5 cm; roof the inferior orbital margin, floor the alveolus, base the lateral nasal wall, apex the zygomatic process; V2 supply.","topic":"The nasal cavity","sec":1,"importance":"core","highYield":"untested"},{"id":"anat3-sinuses:e9","text":"The nasolacrimal duct opens into the inferior meatus.","topic":"The nasal cavity","sec":1,"importance":"core","highYield":"untested"},{"id":"anat3-sinuses:e2","text":"Four sinuses: ethmoidal, sphenoidal, maxillary, frontal. Functions: lighten the skull, add resonance.","topic":"The paranasal sinuses","sec":2,"importance":"core","highYield":"untested"},{"id":"anat3-sinuses:e3","text":"Sinuses are rudimentary at birth, enlarge at 6 to 7 years, then after puberty; lined by respiratory epithelium.","topic":"The paranasal sinuses","sec":2,"importance":"core","highYield":"untested"},{"id":"anat3-sinuses:e5","text":"Ethmoidal: three sets of cells, 3 to 18 per side; ethmoid bulla from the middle cells; V1 and V2 supply.","topic":"Sinus by sinus","sec":3,"importance":"core","highYield":"untested"},{"id":"anat3-sinuses:e7","text":"Sphenoidal: pituitary and optic chiasma above, cavernous sinus and CN III, IV, V1, V2, VI laterally.","topic":"Sinus by sinus","sec":3,"importance":"core","highYield":"untested"},{"id":"anat3-sinuses:e4","text":"Frontal sinus: average 2.5 cm, triangular, drains to the middle meatus via the frontonasal duct, supplied by V1.","topic":"Where each sinus opens","sec":4,"importance":"core","highYield":"untested"},{"id":"anat3-sinuses:e8","text":"Openings: maxillary, frontal and anterior/middle ethmoidal to the middle meatus; posterior ethmoidal to the superior meatus; sphenoidal to the spheno-ethmoidal recess.","topic":"Where each sinus opens","sec":4,"importance":"core","highYield":"untested"}],"vmap":{},"mlevel":{"hkaauk":"a","jenvf8":"a","vd6uwl":"a","192fmqn":"a","1bxjey":"a","10ehpsb":"a","1hkudmk":"a","uqvkm5":"a","4ifcid":"a","1eyrafo":"a","1h8nkhj":"a","1jgypdx":"a","f2v3n3":"a","xuzhu9":"a","vda53v":"a","u2si5s":"a","15syoh1":"a","11tsyom":"a","1jps8qi":"a","2652a0":"a","c62vke":"a","1fgs5c4":"a","1f5nfo":"a","169igjo":"a"},"mapCounts":{"verified":0,"auto":24,"ambiguous":0,"missing":0},"mrules":[],"items":[],"experimental":[],"status":{},"difficulty":{},"expl":{"anat3-sinuses:s0":{"s":0,"u":["Four air-filled sinuses sit in the bones around the nose, and every one of them drains back into the nasal cavity.","If you learn nothing else, learn where each one opens , because that single fact explains sinusitis, why infection spreads, and half the exam questions."],"dp":[]},"anat3-sinuses:e0":{"s":1,"u":["Nares open onto the face; choanae open into the nasopharynx.","Choanae: open into the nasopharynx.","Nares: the external opening of the nose."],"dp":[]},"anat3-sinuses:e1":{"s":1,"u":["Four air channels: inferior, middle and superior meatuses plus the spheno-ethmoidal recess.","Spheno-ethmoidal recess: Between the superior concha and the nasal roof.","The conchae divide each nasal cavity into four air channels:"],"dp":[{"h":"Note","t":"Sphenoid opening: this lecture says sphenoethmoidal recess ; the nasal cavity lecture lists it with the superior meatus region. The recess lies above the superior concha ; give 'sphenoethmoidal recess' unless your professor says otherwise."}]},"anat3-sinuses:e6":{"s":1,"u":["Maxillary: the largest, 3.5 x 2.5 x 3.5 cm; roof the inferior orbital margin, floor the alveolus, base the lateral nasal wall, apex the zygomatic process; V2 supply.","Inferior nasal meatus: Between the inferior concha and the nasal floor.","Elongated wedge-shaped spaces with a large inferior base and a narrow superior apex."],"dp":[{"h":"Note","t":"Maxillary sinus = largest; roof = orbital floor, floor = alveolar process (molar roots), base = lateral nasal wall. Nerve = V2 . Frontal sinus = V1 ."}]},"anat3-sinuses:e9":{"s":1,"u":["The nasolacrimal duct opens into the inferior meatus.","Inferior nasal meatus: Between the inferior concha and the nasal floor.","Middle nasal meatus: Between the inferior and middle conchae."],"dp":[]},"anat3-sinuses:e2":{"s":2,"u":["Four sinuses: ethmoidal, sphenoidal, maxillary, frontal. Functions: lighten the skull, add resonance.","Functions: they make the skull lighter and add resonance to the voice.","There are four paranasal air sinuses: the ethmoidal cells, sphenoidal, maxillary and frontal sinuses."],"dp":[]},"anat3-sinuses:e3":{"s":2,"u":["Sinuses are rudimentary at birth, enlarge at 6 to 7 years, then after puberty; lined by respiratory epithelium.","All are lined by respiratory epithelium.","Development: rudimentary or even absent at birth; enlarge rapidly at the age of 6 to 7 years, then again after puberty."],"dp":[{"h":"Note","t":"Sinuses are rudimentary or absent at birth (maxillary and ethmoid are present early; frontal develops by ~7-8 years), enlarging at 6-7 years and after puberty. A frontal sinusitis in a toddler is unlikely."}]},"anat3-sinuses:e5":{"s":3,"u":["Ethmoidal: three sets of cells, 3 to 18 per side; ethmoid bulla from the middle cells; V1 and V2 supply.","Ethmoidal sinus Composed of three sets of ethmoidal air cells: anterior, middle and posterior , with 3 to 18 cells on each side.","Ethmoid bulla: the middle ethmoid air cells produce this swelling on the lateral wall of the middle meatus."],"dp":[{"h":"Why ethmoid infection threatens the eye","t":"The ethmoidal labyrinth lies between the orbits and the nasal fossae, separated from the orbit only by the lamina papyracea, the paper-thin orbital plate of the ethmoid. Infection in the ethmoidal cells can cross that sheet into the orbit, which is why orbital cellulitis in children most often begins as ethmoid sinusitis. Source: the lecture's ethmoidal labyrinth description, read with the orbital wall anatomy."},{"h":"Memory aid","t":"The middle meatus is the busy one : everything except the posterior ethmoid cells and the sphenoid drains there (hiatus semilunaris, ethmoidal infundibulum, bulla)."}]},"anat3-sinuses:e7":{"s":3,"u":["Sphenoidal: pituitary and optic chiasma above, cavernous sinus and CN III, IV, V1, V2, VI laterally.","Superior: the hypophyseal fossa, pituitary gland and optic chiasma.","Lateral: the cavernous sinus, internal carotid artery and cranial nerves III, IV, V1, V2 and VI."],"dp":[{"h":"Why the sphenoid sinus is a surgical corridor","t":"The lecture's list of relations is not idle detail. Because the pituitary sits directly above the sphenoidal sinus, surgeons reach pituitary tumours by going through the nose and the sinus rather than opening the skull: the trans-sphenoidal approach. The same list explains the risk: the internal carotid artery and CN III, IV, V1, V2 and VI lie in the lateral wall, millimetres away. Source: the lecture's sphenoidal sinus relations slide."},{"h":"Note","t":"Sphenoid sinus relations : above = pituitary (sella) and optic chiasm ; laterally = cavernous sinus with the ICA and CN III, IV, V1, V2, VI. Basis of trans-sphenoidal pituitary surgery."}]},"anat3-sinuses:e4":{"s":4,"u":["Frontal sinus: average 2.5 cm, triangular, drains to the middle meatus via the frontonasal duct, supplied by V1.","Frontal: Opening = Frontonasal duct, frontal ostium; Location = Frontal recess of the middle meatus; Constancy = Constant.","Frontal: Location = Middle meatus via the ethmoidal infundibulum; Constancy = Inconstant."],"dp":[]},"anat3-sinuses:e8":{"s":4,"u":["Openings: maxillary, frontal and anterior/middle ethmoidal to the middle meatus; posterior ethmoidal to the superior meatus; sphenoidal to the spheno-ethmoidal recess.","Ethmoidal, anterior cells: Opening = Ostia of the anterior ethmoidal air cells; Location = Middle meatus via the ethmoidal infundibulum, or via the frontal recess; Constancy = Inconstant.","Ethmoidal, middle cells: Opening = Ostia of the middle ethmoidal air cells; Location = Middle meatus; Constancy = Constant."],"dp":[{"h":"Note","t":"Where each sinus opens : maxillary, frontal, anterior and middle ethmoidal → middle meatus ; posterior ethmoidal → superior meatus ; sphenoid → sphenoethmoidal recess . Nasolacrimal duct → inferior meatus ."}]}},"meta":{"hkaauk":{"a":"recall","vg":"anat3-sinuses:e6/recall/1"},"jenvf8":{"a":"recall","vg":"anat3-sinuses:e0/recall/1"},"vd6uwl":{"a":"recall","vg":"anat3-sinuses:e1/recall/1"},"192fmqn":{"a":"recall","vg":"anat3-sinuses:e9/recall/1"},"1bxjey":{"a":"recall","vg":"anat3-sinuses:e2/recall/1"},"10ehpsb":{"a":"recall","vg":"anat3-sinuses:e2/recall/2"},"1hkudmk":{"a":"recall","vg":"anat3-sinuses:e3/recall/1"},"uqvkm5":{"a":"recall","vg":"anat3-sinuses:e3/recall/2"},"4ifcid":{"a":"recall","vg":"anat3-sinuses:e4/recall/1"},"1eyrafo":{"a":"recall","vg":"anat3-sinuses:e4/recall/2"},"1h8nkhj":{"a":"recall","vg":"anat3-sinuses:e4/recall/3"},"1jgypdx":{"a":"recall","vg":"anat3-sinuses:e5/recall/1"},"f2v3n3":{"a":"recall","vg":"anat3-sinuses:e5/recall/2"},"xuzhu9":{"a":"recall","vg":"anat3-sinuses:e7/recall/1"},"vda53v":{"a":"recall","vg":"anat3-sinuses:e8/recall/1"},"u2si5s":{"a":"recall","vg":"anat3-sinuses:e2/recall/3"},"15syoh1":{"a":"recall","vg":"anat3-sinuses:e6/recall/2"},"11tsyom":{"a":"recall","vg":"anat3-sinuses:e7/recall/1"},"1jps8qi":{"a":"recall","vg":"anat3-sinuses:e7/recall/2"},"2652a0":{"a":"recall","vg":"anat3-sinuses:e1/recall/2"},"c62vke":{"a":"recall","vg":"anat3-sinuses:e4/recall/4"},"1fgs5c4":{"a":"recall","vg":"anat3-sinuses:e7/recall/2"},"1f5nfo":{"a":"recall","vg":"anat3-sinuses:e7/recall/3"},"169igjo":{"a":"recall","vg":"anat3-sinuses:e1/recall/3"}},"explRev":"692fc60102ab"};
